const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export const ARCHITECTURE_PARTS={
 local:{title:'Lokaler Arbeitsrechner',text:'Anna bearbeitet ihre Editionsdateien auf ihrem Rechner. Im bevorzugten Weg nutzt sie eine vorbereitete oXygen-Author-Umgebung, TEI-Schema, Git-Anbindung und lokale Vorschau. Der Markdown-Weg verwendet Texteditor, dokumentierte Konventionen und passende Prüfungen. Änderungen sind erst dann außerhalb dieses Rechners gesichert, wenn sie zum vereinbarten externen Repo übertragen wurden.'},
 work:{title:'Privates Arbeitsrepo',text:'Das Arbeitsrepo hält die erfassten Dateien und ihre Git-Geschichte für den vereinbarten Lesekreis bereit. Regelmäßige Commits und Pushs zu einem verlässlich betriebenen Dienst können die Editionsdateien gegen Rechnerverlust absichern. Beratung ist eine eigene Leistung; sie folgt nicht allein aus einem GitLab-Zugang. Interne XML-Kommentare können in älteren Arbeitsständen erhalten bleiben.'},
 release:{title:'Bewusste Freigabe und Ausgabe',text:'Dies ist ein Arbeitsschritt, kein zusätzlicher Speicherort. Anna wählt einen geprüften Stand aus, klärt Rechte und Metadaten, entfernt interne Arbeitsnotizen und dokumentiert Beiträge sowie Freigabeumfang. Sie exportiert die freigegebenen Dateien ohne die private Git-Geschichte. Ein passender Ausgabeweg erzeugt bei Bedarf HTML oder PDF; rohes TEI wird nicht von selbst zur fertigen Website.'},
 publication:{title:'Öffentliches Publikationsrepo',text:'Das eigene Publikationsrepo enthält nur bewusst freigegebene Daten, Editionsprinzipien, Metadaten, Nutzungsbedingungen und bezeichnete Freigabestände. Es kann auf demselben oder einem anderen Hostingdienst liegen als das Arbeitsrepo. Eine zusätzliche statische Leseansicht kann etwa über GitHub Pages bereitgestellt werden, wenn der Ausgabeweg eingerichtet ist. Das private Arbeitsrepo wird dafür nicht einfach öffentlich geschaltet.'},
 archive:{title:'Vereinbarte Archivübergabe',text:'Ein geeigneter Archivdienst übernimmt einen definierten Datenstand samt Metadaten nach einer Vereinbarung. Langfristige Verantwortung, Zugangsbedingungen und eine persistente Kennung – zum Beispiel DOI – werden gesondert geklärt. Git-Hosting erzeugt weder automatisch ein Archiv noch automatisch eine DOI. Welche Arbeitsgeschichte gegebenenfalls gesondert aufbewahrt wird, ist eine eigene Entscheidung.'}
};
const icon=(type,x,y)=>{const start=`<g transform="translate(${x} ${y})" fill="none" stroke="#173c39" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">`,end='</g>';if(type==='local')return start+'<rect x="-13" y="-11" width="26" height="18" rx="2"/><path d="M-16 11H16L13 7H-13Z"/>'+end;if(type==='work')return start+'<circle cx="-9" cy="-10" r="3"/><circle cx="10" cy="-5" r="3"/><circle cx="-9" cy="11" r="3"/><path d="M-9-7V8M-8 4C10 4 10 1 10-2"/>'+end;if(type==='release')return start+'<path d="M0-14L13-8V2C13 10 5 14 0 16C-5 14-13 10-13 2V-8Z"/><path d="M-6 0L-1 5L7-5"/>'+end;if(type==='archive')return start+'<rect x="-13" y="-8" width="26" height="22" rx="2"/><path d="M-15-12H15V-6H-15ZM-5 2H5"/>'+end;return start+'<path d="M-14-9H-3L1-5H14V12H-14Z"/><path d="M-5 4L0 9L6 2"/>'+end;};
export function architectureSVG(state=null,interactive=false){
 const tei=!state||state.format==='tei',host=state?.host||'uni-support';
 const workTitle=host==='other'?'Privates Arbeitsrepo auf geeignetem Dienst':'Privates Arbeitsrepo im Uni-GitLab';
 const workInfo=host==='uni-support'?'Abgleich · Git-Geschichte · Beratung als vereinbarte Zusatzleistung':host==='uni-only'?'Abgleich · Git-Geschichte · Beratung nicht im gewählten Angebot':'Abgleich · Git-Geschichte · Zugang und Unterstützung gesondert klären';
 const pubHost=!state?'z. B. auf GitHub · gleicher oder anderer Host möglich':state.publicationHost==='same'?'Auf demselben Host, in einem eigenen Repo':state.publicationHost==='other'?'Auf einem anderen Host, in einem eigenen Repo':'Publikations-Host noch offen';
 const box=(id,x,y,w,h,title,sub,extra,pill)=>{const a=interactive?`class="architecture-node" role="button" tabindex="0" data-architecture-node="${id}" aria-label="${esc(title)} erklären"`:'';return `<g ${a}><title>${esc(ARCHITECTURE_PARTS[id].text)}</title><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="21" fill="${id==='local'||id==='publication'||id==='archive'?'#f3f5f3':'#ffffff'}" stroke="#d4ddd7" stroke-width="1.4"/>${icon(id,x+w/2,y+32)}<text x="${x+w/2}" y="${y+68}" text-anchor="middle" font-size="${w<600?21:24}" font-weight="600" fill="#173c39">${esc(title)}</text><text x="${x+w/2}" y="${y+96}" text-anchor="middle" font-size="${w<600?15:18}" fill="#52645b">${esc(sub)}</text>${extra?`<text x="${x+w/2}" y="${y+120}" text-anchor="middle" font-size="14" fill="#52645b">${esc(extra)}</text>`:''}${pill?`<text x="${x+w-18}" y="${y+23}" text-anchor="end" font-size="10" letter-spacing="1" fill="#52645b">${esc(pill)}</text>`:''}</g>`;};
 const path=(d,both=false)=>`<path d="${d}" fill="none" stroke="#7d958b" stroke-width="1.8" marker-end="url(#architecture-arrow)" ${both?'marker-start="url(#architecture-arrow)"':''}/>`;
 const label=(x,y,text)=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="14" fill="#52645b">${esc(text)}</text>`;
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1100 980" width="1100" height="980" class="architecture-svg" role="${interactive?'group':'img'}" aria-labelledby="architecture-title architecture-desc"><title id="architecture-title">Annas Git-Architektur</title><desc id="architecture-desc">Lokaler Rechner und privates Arbeitsrepo werden bewusst abgeglichen. Eine geprüfte Freigabe erzeugt bereinigte Publikationsdaten ohne private Arbeitsgeschichte. Öffentliches Publikationsrepo und vereinbarte Archivübergabe sind getrennte Funktionen; Website, Beratung und persistente Kennung benötigen eigene Einrichtung oder Vereinbarung.</desc><defs><marker id="architecture-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M1 1L8 5L1 9" fill="none" stroke="#7d958b" stroke-width="1.5"/></marker></defs><rect x="1" y="1" width="1098" height="978" rx="25" fill="#fffefb" stroke="#d4ddd7"/><g font-family="Arial, sans-serif"><text x="35" y="47" font-size="31" font-weight="600" fill="#173c39">Annas Git-Architektur</text>${path('M550 217V274',true)}${label(735,249,'bewusst abgleichen: Push / Pull')}${path('M550 409V473')}${label(735,447,'einen Stand zur Freigabe auswählen')}${path('M550 613V649H285V688')}${path('M550 613V649H815V688')}${label(285,673,'geprüfte Dateien, ohne private Geschichte')}${label(815,673,'vereinbartes Archivpaket')}${box('local',35,80,1030,135,'Lokaler Arbeitsrechner',tei?'oXygen Author · Git-Client · TEI-Dateien · lokale Validierung':'Texteditor · Git-Client · Markdown-Dateien · eigene Prüfregeln','Lokale Vorschau und dokumentierte Editionsprinzipien','ARBEITEN')}${box('work',35,276,1030,133,workTitle,workInfo,'Interne Arbeitsstände und Kommunikation bleiben im passenden Lesekreis','PRIVAT')}${box('release',35,475,1030,138,'Bewusste Freigabe und Ausgabe',tei?'TEI-Prüfung · fachliche Freigabe · Rechte und Metadaten prüfen':'Format-/Verweisprüfung · fachliche Freigabe · Rechte und Metadaten prüfen','Bereinigter Export · bei Bedarf Transformation zu HTML / PDF','ARBEITSSCHRITT')}${box('publication',35,690,500,143,'Eigenes Publikationsrepo','Freigegebene Daten · Releases · optional Leseansicht',pubHost,'ÖFFENTLICH')}${box('archive',565,690,500,143,'Geeigneter Archivdienst','Versionierter Datenstand · Metadaten','Persistente Kennung, z. B. DOI, nach Vereinbarung','ÜBERGABE UND ZUGANG KLÄREN')}<text x="550" y="876" text-anchor="middle" font-size="15" fill="#173c39">Ausgaben sind geplante Möglichkeiten nach einer Freigabe, keine bereits erbrachten Leistungen.</text><text x="550" y="905" text-anchor="middle" font-size="14" fill="#52645b">Unabhängige Sicherung ergänzt den Repo-Abgleich. Git-Hosting, Beratung und Archivierung sind eigene Aufgaben.</text><text x="550" y="945" text-anchor="middle" font-size="12" fill="#52645b">Editionskompass · Anna · ${state?'aktuelle Auswahl':'bevorzugtes Ausgangsmodell mit TEI und institutionellem GitLab'} · 20. Oktober 2026</text></g></svg>`;
}
